using FamilyVeda.Infrastructure.Records;
using FluentAssertions;
using System.Globalization;

namespace FamilyVeda.UnitTests;

public sealed class LabExtractionParserTests
{
    private const string TableHeader = "Test\nResult\nPrevious Result\nDate\nUnits\nRef Interval";

    [Fact]
    public void ParseValues_ExtractsStructuredRows_AndIgnoresFreeText()
    {
        const string text = "Synthetic report only\nHaemoglobin | 12.4 g/dL | 11.0-15.0\nignore this sentence";

        var values = LabExtractionService.ParseValues(text);

        values.Should().ContainSingle().Which.Should().Be(
            new LabExtractionService.ParsedLabValue("Haemoglobin", 12.4m, "g/dL", 11.0m, 15.0m));
    }

    [Fact]
    public void ParseFlags_AcceptsOnlyExplicitBoundedMarker()
    {
        const string text = "Possible trait in prose\nHEREDITARY_FLAG: SYNTH-CARRIER | Explicit synthetic marker | 0.72";

        var flags = LabExtractionService.ParseFlags(text);

        flags.Should().ContainSingle().Which.Should().Be(
            new LabExtractionService.ParsedFlag("SYNTH-CARRIER", "Explicit synthetic marker", 0.72m));
    }

    [Theory]
    [InlineData("SYNTHETIC_ClinOCR_tables_t11_s2.expected.txt", 142, 7.9)]
    [InlineData("SYNTHETIC_ClinOCR_tables_t11_s3.expected.txt", 88, 5.2)]
    public void ParseValues_ExtractsRecognizedClinOcrTablesOnly(string fixture, decimal glucose, decimal hba1c)
    {
        var repositoryRoot = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "../../../../../../"));
        var text = File.ReadAllText(Path.Combine(repositoryRoot, "docs", "evidence", "medical-report-test-data", fixture));

        var values = LabExtractionService.ParseValues(text);

        values.Should().HaveCount(18);
        values.Should().Contain(x => x.Analyte == "Glucose" && x.Value == glucose && x.Low == 70m && x.High == 99m);
        values.Should().Contain(x => x.Analyte == "Hemoglobin A1c" && x.Value == hba1c && x.Low == null && x.High == null);
        values.Should().Contain(x => x.Analyte == "eGFR" && x.Unit == "mL/min/1.73m2" && x.Low == null && x.High == null);
    }

    [Fact]
    public void ParseValues_TableRows_UseCurrentValueAndRejectMalformedFields()
    {
        var text = $"{TableHeader}\nGlucose\n142 H\n126\n03/01/2026\nmg/dL\n70-99\nBad current\none\n126\n03/01/2026\nmg/dL\n70-99\nBad previous\n142\none\n03/01/2026\nmg/dL\n70-99\nBad date\n142\n126\n2026-03-01\nmg/dL\n70-99\nBad unit\n142\n126\n03/01/2026\nmg dL\n70-99\nBad range\n142\n126\n03/01/2026\nmg/dL\n70-\nOverflow\n999999999999999999999999999999\n126\n03/01/2026\nmg/dL\n70-99";

        var values = LabExtractionService.ParseValues(text);

        values.Should().ContainSingle().Which.Should().Be(new LabExtractionService.ParsedLabValue("Glucose", 142m, "mg/dL", 70m, 99m));
    }

    [Fact]
    public void ParseValues_DoesNotParseTableRowsWithoutRecognizedHeader()
    {
        const string text = "Glucose\n142 H\n126\n03/01/2026\nmg/dL\n70-99\nMedication\nAspirin";

        LabExtractionService.ParseValues(text).Should().BeEmpty();
    }

    [Fact]
    public void ParseValues_UsesInvariantCultureForClinOcrNumbers()
    {
        var original = CultureInfo.CurrentCulture;
        try
        {
            CultureInfo.CurrentCulture = CultureInfo.GetCultureInfo("fr-FR");
            var values = LabExtractionService.ParseValues($"{TableHeader}\nCreatinine\n0.70\n0.68\n01/15/2026\nmg/dL\n0.57-1.00");
            values.Should().ContainSingle().Which.Should().Be(new LabExtractionService.ParsedLabValue("Creatinine", 0.70m, "mg/dL", 0.57m, 1.00m));
        }
        finally
        {
            CultureInfo.CurrentCulture = original;
        }
    }

    [Fact]
    public void ParseValues_ExtractsRowPerLineTableAsProducedByRealOcr()
    {
        // Verbatim shape of Tesseract output for SYNTHETIC_ClinOCR_tables_t11_s2.png: flag glued to the value, wrapped header.
        const string text = "Comp. Metabolic Panel\nTest Result Previous Date Units Ref\nResult Interval\nGlucose 142H 126 03/01/2026 mg/dL 70-99\nBUN 22 19 03/01/2026 mg/dL 7-25\neGFR 61 65 03/01/2026 mL/min/1.73m2 >=60\nCarbon Dioxide, Total 23 24 03/01/2026 mEq/L 21-32\nHemoglobin A1c\nTest Result Previous Date Units Ref Interval\nResult\nHemoglobin A1c 7.9H 7.5 03/01/2026 % <5.7\n";

        var values = LabExtractionService.ParseValues(text);

        values.Select(x => (x.Analyte, x.Value, x.Unit, x.Low, x.High)).Should().Equal(
            ("Glucose", 142m, "mg/dL", 70m, 99m),
            ("BUN", 22m, "mg/dL", 7m, 25m),
            ("eGFR", 61m, "mL/min/1.73m2", (decimal?)null, (decimal?)null),
            ("Carbon Dioxide, Total", 23m, "mEq/L", 21m, 32m),
            ("Hemoglobin A1c", 7.9m, "%", (decimal?)null, (decimal?)null));
    }

    [Fact]
    public void ParseValues_IgnoresRowPerLineRowsWithoutHeaderOrWithMalformedFields()
    {
        LabExtractionService.ParseValues("Glucose 142H 126 03/01/2026 mg/dL 70-99\n").Should().BeEmpty();
        LabExtractionService.ParseValues("Test Result Previous Date Units Ref\nGlucose 142H 126 13/45/2026 mg/dL 70-99\nBUN 22 03/01/2026 mg/dL 7-25\nPotassium 3.8 4.0 03/01/2026 mEq/L about normal\n").Should().BeEmpty();
    }
}
